StructuralRule.Predicate:
FunctionCall:
    possibleTargets contains [Function:
        name == "setNavigationDelegate"
        and enclosingClass.supers contains [Class:
            name matches "(WebKit\.)?WKWebView"
        ]
    ]
    and (
        /* Delegate is nil */
        (arguments[0].constantValue is [Null:] or arguments[0].constantValue == 0)
        /* Delegate does not properly validate links */
        or arguments[0] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "WKNavigationDelegate_LinkValidation"]]
            and not type is [Type: definition.supers contains [Class: labels contains "WKNavigationDelegate_LinkValidation"]]
        ]
    )
    and not enclosingFunction reachedBy [Function:
        name == "dealloc"
        or name == "viewDidDisappear"
        or name == "viewWillDisappear"
        or name == "viewDidUnload"
    ]

FunctionCall:
    possibleTargets contains [Function:
        name == "setDelegate"
        and enclosingClass.supers contains [Class:
            name matches "(UIKit\.)?UIWebView"
        ]
    ]
    and (
        /* Delegate is nil */
        (arguments[0].constantValue is [Null:] or arguments[0].constantValue == 0)
        /* Delegate does not properly validate links */
        or arguments[0] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "UIWebViewDelegate_LinkValidation"]]
            and not type is [Type: definition.supers contains [Class: labels contains "UIWebViewDelegate_LinkValidation"]]
        ]
    )
    and not enclosingFunction reachedBy [Function:
        name == "dealloc"
        or name == "viewDidDisappear"
        or name == "viewWillDisappear"
        or name == "viewDidUnload"
    ]

FunctionCall:
    possibleTargets contains [Function:
        (name == "init^:user:password:persistence"
        or name == "init^:identity:certificates:persistence")
        and enclosingClass.supers contains [Class:
            name matches "(Foundation\.)?NSURLCredential"
        ]
    ]
    and arguments[2] is [FunctionCall:
        possibleTargets contains [Function:
            name == "Synchronizable"
        ]
    ]

Class:
    /* AppDelegate */
    labels contains "UIApplicationDelegate"
    /* ... and it implements it but it does not check or does not return false */
    and functions contains [Function f:
        name == "application:shouldAllowExtensionPointIdentifier"
        and (
            not contains [VariableAccess:
                variable.name == "UIApplicationKeyboardExtensionPointIdentifier"
            ]
            or not contains [ReturnStatement: 
                /* see bug 57773 */
                expression.constantValues contains [Boolean: is false]
                or expression contains [VariableAccess: 
                    variable is [Variable:
                        /* see bug 58623 */
                        not enclosingFunction.null and 
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and rhs.constantValues contains [Boolean: is false]
                            ]
                        ]
                    ]
                ]
            ]
        )
    ]*

Class:
    /* AppDelegate */
    labels contains "UIApplicationDelegate"
    /* ... and it either does not implement shouldAllowExtensionPointIdentifier callback */
    and not functions contains [Function:
        /* When checking that a function does not exist, need to check for swift 2 and swift 3 signatures */
        name == "application:_:shouldAllowExtensionPointIdentifier:"
        or name == "application:shouldAllowExtensionPointIdentifier"
    ]

Class:
    /* SLComposeServiceViewController */
    supers contains [Class: 
        name matches "(Social\.)?SLComposeServiceViewController"
    ]
    /* ... and it either does not implement isContentValid callback */
    and (not functions contains [Function:
        name == "isContentValid"
    ]
    /* ... or it implements it but it does not return false */
     or functions contains [Function f:
         name == "isContentValid"
         and not contains [ReturnStatement: 
            /* see bug 57773 */
            expression.constantValues contains [Boolean: is false]
            or expression contains [VariableAccess: 
                variable is [Variable:
                    /* see bug 58623 */
                    not enclosingFunction.null and 
                    uses contains [VariableAccess va:
                        enclosingStatement is [AssignmentStatement:
                            lhs is [VariableAccess va2: va2 is va]
                            and rhs.constantValues contains [Boolean: is false]
                        ]
                    ]
                ]
            ]
         ]
    ]*)

Class:
    /* Application Delegate */
    labels contains "UIApplicationDelegate"
    /* ... which contains a handler for custom URL IPC */
    and functions contains [Function:
        name == "application:handleOpenURL"
        or name == "application:openURL:sourceApplication:annotation"
        or name == "application:openURL:options"
    ]*
    /* ... and it either does not implement any of the callbacks where validation can stop the application launching */
    and (not functions contains [Function:
        /* When checking that a function does not exist, need to check for swift 2 and swift 3 signatures */
        name == "application:_:willFinishLaunchingWithOptions:"
        or name == "application:willFinishLaunchingWithOptions"
        or name == "application:_:didFinishLaunchingWithOptions:"
        or name == "application:didFinishLaunchingWithOptions"
    ]
    /* ... or it implements it but they do not access the URL used to call the app or does not return false */
    or functions contains [Function f:
        (name == "application:willFinishLaunchingWithOptions"
        or name == "application:didFinishLaunchingWithOptions")
        and (
            not contains [VariableAccess:
                variable.name == "UIApplicationLaunchOptionsURLKey"
            ]
            or not contains [ReturnStatement: 
                /* see bug 57773 */
                expression.constantValues contains [Boolean: is false]
                or expression contains [VariableAccess: 
                    variable is [Variable:
                        /* see bug 58623 */
                        not enclosingFunction.null and 
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and rhs.constantValues contains [Boolean: is false]
                            ]
                        ]
                    ]
                ]
            ]
        )
    ]*)

Class:
    /* Application Delegate */
    labels contains "UIApplicationDelegate"
    /* ... which contains a handler for custom URL IPC */
    and functions contains [Function:
        name == "application:handleOpenURL"
        or name == "application:openURL:sourceApplication:annotation"
        or name == "application:openURL:options"
    ]*

FunctionCall:
    possibleTargets contains [Function:
        name matches "init\^:request:delegate(:startImmediately)?"
        and enclosingClass.supers contains [Class:
            name matches "(Foundation\.)?NSURLConnection"
        ]
    ]
    and arguments[0] is [Expression request:]
    and (
        /* Delegate is nil */
        (arguments[1].constantValue is [Null:] or arguments[1].constantValue == 0)
        /* Delegate does cache responses */
        or arguments[1] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "NSURLConnectionDataDelegate_NoCache"]]
            and not type is [Type: definition.supers contains [Class: labels contains "NSURLConnectionDataDelegate_NoCache"]]
        ]
    )

FunctionCall: 
    possibleTargets contains [Function:
        name matches "CCSymmetricKeyWrap|CCSymmetricKeyUnwrap"
    ]
    and (
        arguments[1].constantValue is [Null:]
        or arguments[1].constantValue == 0
        or arguments[1].constantValue == ""
        /* if iv is non-constant and has the same non-constant value as the key */
        or (arguments[1].constantValue.null and arguments[1] == arguments[3])
        /* if iv is constant and has the same constant value as the key */
        or (not arguments[1].constantValue.null 
        and arguments[1].constantValue == arguments[3].constantValue) 
        /* if iv is constant (hardcoded) */
        or not arguments[1].constantValue.null
    )

FunctionCall: 
    possibleTargets contains [Function:
        name == "CCCryptorCreateWithMode"
    ]
    and (
        arguments[4].constantValue is [Null:]
        or arguments[4].constantValue == 0
        or arguments[4].constantValue == ""
        /* if iv is constant (hardcoded) */
        or not arguments[4].constantValue.null
        /* if iv is non-constant and has the same non-constant value as the key */
        or (arguments[4].constantValue.null and arguments[4] == arguments[5])
        /* if iv is constant and has the same constant value as the key */
        or (not arguments[4].constantValue.null and arguments[4].constantValue == arguments[3].constantValue) 
    )

FunctionCall: 
    possibleTargets contains [Function:
        name matches "CCCrypt|CCCryptorCreate(FromData)?"
    ]
    and (
        arguments[5].constantValue is [Null:]
        or arguments[5].constantValue == 0
        or arguments[5].constantValue == ""
        /* if iv is constant (hardcoded) */
        or not arguments[5].constantValue.null
        /* if iv is non-constant and has the same non-constant value as the key */
        or (arguments[5].constantValue.null and arguments[5] == arguments[3])
        /* if iv is constant and has the same constant value as the key */
        or (not arguments[5].constantValue.null and arguments[5].constantValue == arguments[3].constantValue) 
    )

FunctionCall fc:
    possibleTargets contains [Function:
        name == "archiveRootObject:toFile" and enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSKeyedArchiver"]
    ] 
    and enclosingFunction is [Function fileAccessFunction: 
        not fileAccessFunction contains [FunctionCall: 
            function.name == "setAttributes:ofItemAtPath"
            and function.enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSFileManager"]
            and (arguments[1] is [VariableAccess:
                variable is [Variable file1:
                    fc.arguments[1] is [VariableAccess:
                        variable is file1
                    ]
                ]
            ] or arguments[1] is [FunctionCall file2:
                fc.arguments[1] is [FunctionCall:
                    function.name == file2.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
        and not fileAccessFunction contains [FunctionCall:
            function.name == "createFileAtPath:contents:attributes"
            and function.enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSFileManager"]
            and (arguments[0] is [VariableAccess:
                variable is [Variable file3:
                    fc.arguments[1] is [VariableAccess:
                        variable is file3
                    ]
                ]
            ] or arguments[1] is [FunctionCall file4:
                fc.arguments[1] is [FunctionCall:
                    function.name == file4.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
    ]

