                    rhs is [FunctionCall: 
                        possibleTargets contains [Function:
                            name matches "DataWritingFileProtectionComplete(UnlessOpen|UntilFirstUserAuthentication)" 
                            and enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSDataWritingOptions"]
