AssignmentStatement as:
    rhs is [Allocation:
        constructor is [FunctionCall fc:
            possibleTargets contains [Function:
                (name == "init^:URL" or constructor)
                and enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSURLRequest"]
            ]
        ]
    ]
    and (lhs is [VariableAccess:
        variable is [Variable request1:
            not as.enclosingFunction contains [FunctionCall:
                 function is [Function:
                     name matches "setHTTPMethod|httpMethod:_:"
                     and enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSMutableURLRequest"]
                 ]
                 and instance is [VariableAccess:
                    variable is [Variable request2:
                        request2 is request1
                    ]
                ]
            ]
        ]
    ]
    or lhs is [FieldAccess:
        field is [Field request3:
            not as.enclosingFunction contains [FunctionCall:
                function is [Function:
                    name matches "setHTTPMethod|httpMethod:_:"
                    and enclosingClass.supers contains [Class: name matches "(Foundation\.)?NSMutableURLRequest"]
                ]
                and instance is [FieldAccess:
                    field is [Field request4:
                        request3 is request4
                    ]
                ]
            ]
        ]
    ])

