CharacterizationRule.StructuralMatch:
FunctionCall fc:
     arguments contains [FunctionCall:
         possibleTargets contains [Function:
             name == "DocumentDirectory"
             and enclosingClass.supers contains [Class:
                name == "DocumentDirectory"
            ]
         ]
     ]

FunctionCall fc:
    possibleTargets contains [Function:
        (name == "init^:user:password:persistence"
        or name == "init^:identity:certificates:persistence")
        and enclosingClass.supers contains [Class:
            name matches "(Foundation\.)?NSURLCredential"
        ]
    ]
    and arguments[2] is [FunctionCall:
        possibleTargets contains [Function:
            name == "Synchronizable"
        ]
    ]

FunctionCall fc:
     arguments[0] is [Expression conf:]
     /* No delegate specified */
     and (possibleTargets contains [Function:
         name == "init^:configuration"
         and enclosingClass.supers contains [Class:
             name matches "(Foundation\.)?NSURLSession"
         ]
     ]
     /* Delegate is nil */
     or possibleTargets contains [Function:
         name == "init^:configuration:delegate:delegateQueue"
         and enclosingClass.supers contains [Class:
             name matches "(Foundation\.)?NSURLSession"
         ]
         and (fc.arguments[1].constantValue is [Null:] or fc.arguments[1].constantValue == 0)
