             not reachingTypes contains [Type: definition.supers contains [Class: labels contains "NSURLSessionDataDelegate_NoCache"]]
             and not type is [Type: definition.supers contains [Class: labels contains "NSURLSessionDataDelegate_NoCache"]]
         ]
     ])

