DataflowSourceRule.Script:
var pattern = "";
for (var key in program.plist_ssl_urls_vars) {
    var name = String(program.plist_ssl_urls_vars[key]);
    if (pattern != "") pattern += "|";
    pattern += name;
}
if (pattern == "") pattern = "FORTIFY_NON_EXISTANT";
rule.Conditional.ConstantMatches.Pattern = pattern;

var pattern = "";
for (var key in program.plist_file_urls_vars) {
    var name = String(program.plist_file_urls_vars[key]);
    if (pattern != "") pattern += "|";
