}
if (pattern == "") pattern = "FORTIFY_NON_EXISTANT";
rule.Conditional.ConstantMatches.Pattern = pattern;

var pattern = "";
for (var key in program.plist_non_ssl_urls_vars) {
    var name = String(program.plist_non_ssl_urls_vars[key]);
    if (pattern != "") pattern += "|";
