      name == "setHidden" 
    ] 
    and arguments[0] is [BooleanLiteral: value is true]
    and enclosingFunction is [Function callback:
        callback.enclosingClass is [Class viewController:
            viewController.supers contains [Class: name matches "(UIKit\.)?UIViewController"] 
            and viewController.functions contains [Function register: 
                register contains [FunctionCall addObserver: 
                    possibleTargets contains [Function:
                        name == "addObserver:selector:name:object" 
