        ]
    ]
    and instance is [FunctionCall getter:
        possibleTargets contains [Function:
            enclosingClass.fields contains [Field field:
                name == getter.name
            ]
        ]
    ]

Function:
    name matches "URLSession:didReceiveChallenge:completionHandler"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name matches "(Security\.)?SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name == "URLSession:task:didReceiveChallenge:completionHandler"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name matches "(Security\.)?SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name matches "connection:didReceiveAuthenticationChallenge|connection:willSendRequestForAuthenticationChallenge"
    and reaches [Function:
        contains [FunctionCall:
            function is [Function:
                name matches "(Security\.)?SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name == "webView:didReceiveAuthenticationChallenge:completionHandler"
    and reaches [Function:
        contains [FunctionCall:
            possibleTargets contains [Function:
                name matches "(Security\.)?SecTrustGetCertificateAtIndex"
            ]
        ]
    ]
    and enclosingClass is [Class delegate:]

Function:
    name == "URLSession:dataTask:willCacheResponse:completionHandler"
    and enclosingClass is [Class delegate:]
    and contains [FunctionPointerCall: 
        functionPointer is [FieldAccess:
            field.name == "~function"
            and instance is [VariableAccess:
                variable.name == "completionHandler"
            ]
        ]
        /* either we find that the function returns nil */
        and (arguments contains [Expression: constantValues contains [Null:]]
        /* or that it returns a variable that may contain nil as value */
        /* see bug 57773 */
        or arguments contains [VariableAccess: 
            variable is [Variable:
                /* see bug 58623 */
                not enclosingFunction.null and 
                uses contains [VariableAccess va:
                    enclosingStatement is [AssignmentStatement:
                        lhs is [VariableAccess va2: va2 is va]
                        and rhs.constantValues contains [Null:]
                    ]
                ]
            ]
        ])
    ]

ReturnStatement:
    /* either we find that the function returns nil */
    (expression is [Expression: constantValues contains [Null:]]
    /* or that it returns a variable that may contain nil as value */
    /* see bug 57773 */
    or expression is [VariableAccess: 
        variable is [Variable:
            /* see bug 58623 */
            not enclosingFunction.null and 
            uses contains [VariableAccess va:
                enclosingStatement is [AssignmentStatement:
                    lhs is [VariableAccess va2: va2 is va]
                    and rhs.constantValues contains [Null:]
                ]
            ]
        ]
    ])
    and enclosingFunction is [Function:
        name == "connection:willCacheResponse"
        and enclosingClass is [Class delegate:]
    ]

Function:
    name == "webView:decidePolicyForNavigationAction:decisionHandler"
    and enclosingClass is [Class delegate:]
    and contains [FunctionPointerCall: 
        functionPointer is [FieldAccess:
            instance is [VariableAccess:
                variable.name == "decisionHandler"
            ]
        ]
        and arguments contains [FunctionCall:
            possibleTargets contains [Function:
                name == "Cancel"
            ]
        ]
    ]

Description.Explanation:
HTTP requests which utilize the <code>GET</code> method allow the URL and request parameters to be cached in the browser's URL cache, intermediary proxies, and server logs. This could expose sensitive information to individuals who do not have appropriate rights to the data.
<b>Example 1:</b> The following code makes an HTTP request using the GET HTTP method instead of POST.

<pre>
...
let url = NSURL(string: "https://www.somesvr.com/someapp/user")
let request = NSMutableURLRequest(URL: url!)
request.HTTPMethod = "GET"
let connection = NSURLConnection(request:request, delegate:self)
...
</pre>

<b>Example 2:</b> If the application uses NSURLRequest then the default HTTP method is GET.

<pre>
...
let url = NSURL(string: "https://www.somesvr.com/someapp/user")
let request = NSURLRequest(URL: url!)
let connection = NSURLConnection(request:request, delegate:self)
...
</pre>

In some libraries that involve SSL connections, the server certificate is not verified by default (or can be explicitly configured to do so). This is equivalent to trusting all certificates.

<b>Example 1:</b> This code configures <code>NSURLConnectionDelegate</code> to accept any HTTPS certificate:

<pre>
class Delegate: NSObject, NSURLConnectionDelegate {

    ...

    func connection(connection: NSURLConnection, canAuthenticateAgainstProtectionSpace protectionSpace: NSURLProtectionSpace?) -> Bool {
        return protectionSpace?.authenticationMethod == NSURLAuthenticationMethodServerTrust
    }

    func connection(connection: NSURLConnection, willSendRequestForAuthenticationChallenge challenge: NSURLAuthenticationChallenge) {
        challenge.sender?.useCredential(NSURLCredential(forTrust: challenge.protectionSpace.serverTrust!), forAuthenticationChallenge: challenge)
        challenge.sender?.continueWithoutCredentialForAuthenticationChallenge(challenge)
    }
}
</pre>

When trying to connect to an SSL-secured server using the implementation of <code>NSURLConnectionDelegate</code> from <code>Example 1</code>, no warnings or errors will result if the requested server's certificate is self-signed (and therefore unverified). As a result, the application would now potentially leak sensitive user information over the broken SSL connection.

<b>Example 2:</b> In an <code>NSURLSession</code> class, the SSL/TLS chain validation is handled by your app's authentication delegate method, but instead of providing credentials to authenticate the user (or your app) to the server, your app instead checks the credentials that the server provides during the SSL/TLS handshake, then tells the URL loading system whether it should accept or reject those credentials. The following code shows an <code>NSURLSessionDelgate</code> that just passes <code>proposedCredential</code> of the challenge received back as a credential for the session, effectively bypassing the server verification:

<pre>
class MySessionDelegate : NSObject, NSURLSessionDelegate {
    ...
    func URLSession(session: NSURLSession, didReceiveChallenge challenge: NSURLAuthenticationChallenge, completionHandler: (NSURLSessionAuthChallengeDisposition, NSURLCredential?) -> Void) {
        ...
        completionHandler(NSURLSessionAuthChallengeDisposition.UseCredential, challenge.proposedCredential)
        ...
    }
    ...
}
</pre>

Description.Recommendations:
When reviewing an application that contains one or more Insecure Storage: Lacking Data Protection issues, it is likely that one will determine that a given resource should have stricter protection. Starting in iOS 7, if the user has enabled a passcode for their device, Data Protection is enabled by default, and all third party application data is assigned the Data Protection class <code>NSFileProtectionCompleteUntilFirstUserAuthentication</code>. However, even though this is an improvement over the default Data Protection class in earlier versions of iOS -- <code>NSFileProtectionNone</code> -- any data assigned <code>NSFileProtectionCompleteUntilFirstUserAuthentication</code> will remain continuously accessible while the device is powered on after the user enters their passcode for the first time post-boot. One should always use the strictest Data Protection class possible within the constraints of the given application's functionality.

In the following examples (representing solutions to the issues demonstrated in <code>Example 1</code> and <code>Example 2</code> respectively), the given resource is protected at all times except when the device is powered on and unlocked:

<b>Example 3:</b>

<pre>
...
let documentsPath = NSURL(fileURLWithPath: NSSearchPathForDirectoriesInDomains(.DocumentDirectory, .UserDomainMask, true)[0])
let filename = "\(documentsPath)/tmp_activeTrans.txt"
let protection = [NSFileProtectionKey: NSFileProtectionComplete]
do {
    try NSFileManager.defaultManager().setAttributes(protection, ofItemAtPath: filename)
} catch let error as NSError {
    NSLog("Unable to change attributes: \(error.debugDescription)")
}
...
BOOL ok = textToWrite.writeToFile(filename, atomically:true)
...
</pre>

<b>Example 4:</b>

<pre>
...
let documentsPath = NSURL(fileURLWithPath: NSSearchPathForDirectoriesInDomains(.DocumentDirectory, .UserDomainMask, true)[0])
let filename = "\(documentsPath)/tmp_activeTrans.txt"
...
BOOL ok = textData.writeToFile(filepath, options: .DataWritingFileProtectionComplete);
...
</pre>

Description.Explanation:
Files saved to iOS's photo album are world-readable and can be accessed by any application on the device. This could allow an attacker to steal sensitive photos, such as those of checks used for mobile check deposits.

<b>Example 1:</b> The following code uses <code>UIImageWriteToSavedPhotosAlbum</code> to save images to the photo album:

<pre>
func imagePickerController(picker: UIImagePickerController, didFinishPickingMediaWithInfo info: [NSObject : AnyObject]) {
    if let pickedImage = info[UIImagePickerControllerOriginalImage] as? UIImage {
        imageView.contentMode = .ScaleAspectFit
        imageView.image = pickedImage
    }

    // Save image
    UIImageWriteToSavedPhotosAlbum(pickedImage!, self, nil, nil)

    dismissViewControllerAnimated(true, completion: nil)
}
</pre>

Description.Recommendations:
Utilize the Data Protection API to provide stricter protection for any sensitive information.

<b>Example 2:</b> The following code uses the Data Protection components of <code>NSFileManager</code> and <code>NSData</code> to sufficiently encrypt images before saving them to the photo album:

<pre>
func imagePickerController(picker: UIImagePickerController, didFinishPickingMediaWithInfo info: [NSObject : AnyObject]) {
    if let pickedImage = info[UIImagePickerControllerOriginalImage] as? UIImage {
        imageView.contentMode = .ScaleAspectFit
        imageView.image = pickedImage
    }

    // Save image
    let imgData :NSData = UIImageJPEGRepresentation(pickedImage!, 1)!;
    let documentsPath = NSURL(fileURLWithPath: NSSearchPathForDirectoriesInDomains(.DocumentDirectory, .UserDomainMask, true)[0])
    let jpgPath = "\(documentsPath)/Financial.jpg"
    do {
        try imgData.writeToFile(jpgPath, options: .DataWritingFileProtectionComplete)
        try NSFileManager.defaultManager().setAttributes(protection, ofItemAtPath: jpgPath)
    } catch let error as NSError {
        NSLog("Unable to change attributes: \(error.debugDescription)")
    }

    dismissViewControllerAnimated(true, completion: nil)
}
</pre>

